import{_ as t,o as a,c as o,l as i,t as r,N as s}from"./chunks/framework.CMqbtke2.js";const f=JSON.parse('{"title":"git-credential-cache | x-cmd man (git man1) | Helper to temporarily store passwords in memory","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-credential-cache - Helper to temporarily store passwords in memory","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-credential-cache | x-cmd man (git man1) | Helper to temporarily store passwords in memory"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-credential-cache - Helper to temporarily store passwords in memory"}]]},"headers":[],"params":{"isMan":true,"man":"git-credential-cache","category":"git man1","desc":"Helper to temporarily store passwords in memory"},"relativePath":"git/man1/git-credential-cache.md","filePath":"git/man1/git-credential-cache.md"}'),n={name:"git/man1/git-credential-cache.md"},c={class:"visually-hidden"},l=s(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-credential-cache - Helper to temporarily store passwords in memory</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> credential.helper</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;cache [&lt;options&gt;]&#39;</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>This command caches credentials for use by future Git programs. The stored credentials are kept in memory of the cache-daemon process (instead of written to a file) and are forgotten after a configurable timeout. Credentials are forgotten sooner if the cache-daemon dies, for example if the system restarts. The cache is accessible over a Unix domain socket, restricted to the current user by filesystem permissions.</p><p>You probably don&#39;t want to invoke this command directly; it is meant to be used as a credential helper by other parts of Git. See <strong>gitcredentials</strong>(7) or <strong>EXAMPLES</strong> below.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>--timeout &lt;seconds&gt;</p><blockquote><p>Number of seconds to cache credentials (default: 900).</p></blockquote><p>--socket &lt;path&gt;</p><blockquote><p>Use <strong>&lt;path&gt;</strong> to contact a running cache daemon (or start a new cache daemon if one is not started). Defaults to <strong>$XDG_CACHE_HOME/git/credential/socket</strong> unless <strong>~/.git-credential-cache/</strong> exists in which case <strong>~/.git-credential-cache/socket</strong> is used instead. If your home directory is on a network-mounted filesystem, you may need to change this to a local filesystem. You must specify an absolute path.</p></blockquote><h2 id="controlling-the-daemon" tabindex="-1">CONTROLLING THE DAEMON <a class="header-anchor" href="#controlling-the-daemon" aria-label="Permalink to &quot;CONTROLLING THE DAEMON&quot;">​</a></h2><p>If you would like the daemon to exit early, forgetting all cached credentials before their timeout, you can issue an <strong>exit</strong> action:</p><blockquote><pre><code>git credential-cache exit
</code></pre></blockquote><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>The point of this helper is to reduce the number of times you must type your username or password. For example:</p><blockquote><pre><code>$ git config credential.helper cache
$ git push http://example.com/repo.git
Username: &lt;type your username&gt;
Password: &lt;type your password&gt;

[work for 5 more minutes]
$ git push http://example.com/repo.git
[your credentials are used automatically]
</code></pre></blockquote><p>You can provide options via the credential.helper configuration variable (this example increases the cache time to 1 hour):</p><blockquote><pre><code>$ git config credential.helper &#39;cache --timeout=3600&#39;
</code></pre></blockquote><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,22);function d(e,h,p,m,g,u){return a(),o("div",null,[i("h1",c,r(e.$params.man),1),l])}const k=t(n,[["render",d]]);export{f as __pageData,k as default};
